CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region IN (${grass_region})
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND (
        scene_id IN (451, 413, 1361)
        OR experiment_id IN (193244, 217258)
    );

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_data_${grass_region_without_quote} AS
SELECT
    user_id,
    search_entrance,
    image_source,
    platform,
    coalesce(is_ads, false) as is_ads,
    sum(
        if(
            page_type IN ('search', 'home', 'mall', 'pre_search', 'find_similar_products', 'shop_category_landing')
            AND target_type IN ('image_search_button', 'try_image_search_button')
            AND operation = 'impression',
            imp_cnt,
            0
        )
    ) AS image_search_button_imp_cnt,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'impression',
            imp_cnt,
            0
        )
    ) AS image_search_item_imp_cnt,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'click',
            click_cnt,
            0
        )
    ) AS image_search_item_click_cnt,
    sum(
        if(
            page_type IN ('search', 'home', 'mall', 'pre_search', 'find_similar_products', 'shop_category_landing')
            AND target_type IN ('image_search_button', 'try_image_search_button')
            AND operation = 'click',
            click_cnt,
            0
        )
    ) AS image_search_button_click_cnt,
    sum(
        if(
            page_type = 'product'
            AND target_type = 'like_button'
           -- AND liked = false
            AND operation = 'click',
            click_cnt,
            0
        )
    ) AS pdp_like_button_click_cnt,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'click',
            click_location_sum,
            0
        )
    ) AS click_location_sum,
    sum(
        if(
            page_type = 'image_search'
            AND 
            (
                page_section[0] = 'search'
                OR
                page_section[0] IS NULL
            )
            AND target_type = 'item'
            AND operation = 'cart',
            atc_location_sum,
            0
        )
    ) AS atc_location_sum,
    sum(
        if(
            page_type = 'camera_search'
            AND operation = 'view',
            view_cnt,
            0
        )
    ) AS camera_search_pv,
    sum(
        if(
            page_type = 'image_search'
            AND operation = 'view',
            view_cnt,
            0
        )
    ) AS image_search_pv,
    sum(
        if(
            feature_detail IN (
                'image_search-item', 
                'image_search-search-item',
                'image_search-rcmd-item',
                'image_search-original_item-item'
            )
            AND operation = 'ppv',
            ppv_cnt,
            0
        )
    ) AS ppv_pv,
    sum(
        if(
            feature_detail IN (
                'image_search-item', 
                'image_search-search-item',
                'image_search-rcmd-item',
                'image_search-original_item-item'
            )
            AND operation = 'cart',
            cart_cnt,
            0
        )
    ) AS cart_cnt,
    count( DISTINCT
        if(
            page_type = 'image_search'
            AND target_type = 'item'
            AND operation = 'impression',
            md5,
            null
        )
    )AS image_search_result_volume,
    count( DISTINCT
        if(
            page_type = 'image_search'
            AND target_type = 'take_new_photo_button'
            AND operation = 'impression',
            md5,
            null
        )
    ) AS image_search_non_result_volume,
    count(
        if(
            page_type = 'image_search'
            AND operation = 'view',
            md5,
            null
        )
    ) AS query_cnt,
    sum(
        if(
            feature_detail IN (
                'image_search-item', 
                'image_search-search-item',
                'image_search-rcmd-item',
                'image_search-original_item-item'
            )
            AND operation = 'order',
            order_cnt,
            0
        )
    ) AS order_cnt,
    sum(
        if(
            feature_detail IN (
                'image_search-item', 
                'image_search-search-item',
                'image_search-rcmd-item',
                'image_search-original_item-item'
            )
            AND operation = 'order',
            gmv_local,
            0
        )
    ) AS gmv_local,
    sum(
        if(
            feature_detail IN (
                'image_search-item', 
                'image_search-search-item',
                'image_search-rcmd-item',
                'image_search-original_item-item'
            )
            AND operation = 'order',
            gmv,
            0
        )
    ) AS gmv,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item',
            top1_similarity_sum,
            0
        )
    ) AS top1_similarity_sum,
    sum(
        if(
            page_type = 'image_search'
            AND target_type = 'item',
            top1_item_imp_cnt,
            0
        )
    ) AS top1_item_imp_cnt
FROM
    srdi_mart.dwm_sr_data_warehouse_image_search_user
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
    and search_entrance is not null
    and search_entrance <> ''
GROUP BY 1,2,3,4,5;



--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_image_search_entrance_user_exp_metrics_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
)
SELECT
	user_exp_mapping.user_id
    ,exp_group_id
    ,platform
    ,search_entrance
    ,image_source
    ,image_search_button_imp_cnt
	,image_search_item_imp_cnt
    ,image_search_item_click_cnt
    ,image_search_button_click_cnt
	,pdp_like_button_click_cnt
    ,click_location_sum
    ,atc_location_sum
    ,camera_search_pv
    ,image_search_pv
    ,ppv_pv
	,cart_cnt
	,image_search_result_volume
	,image_search_non_result_volume
	,query_cnt
    ,order_cnt
    ,gmv_local
    ,gmv
    ,top1_similarity_sum
    ,top1_item_imp_cnt
    ,is_ads
FROM
    user_exp_mapping_${grass_region_without_quote}  AS user_exp_mapping
INNER JOIN
    dwm_data_${grass_region_without_quote}  AS dwm_data
ON dwm_data.user_id = user_exp_mapping.user_id
    ;
